-- ════════════════════════════════════════════════════════
-- Seed data PM dari export Google Sheets (pm.pdf) → Turso (libSQL/SQLite)
-- Dibuat otomatis. Isi: 203 schedule, 233 laporan, 15 template checklist.
--
-- Aman dijalankan berulang (UPSERT): data yang sudah ada di Turso dan LEBIH BARU
-- tidak ditimpa, dan data yang sudah dihapus di aplikasi tidak dihidupkan lagi.
--
-- Cara jalan (pilih salah satu):
--   D:\Xampp\php\php.exe D:\Xampp\htdocs\PM\tools\seed-turso.php
--   turso db shell <nama-db> < sql/seed-turso.sql
-- ════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS schedules (
    id             TEXT PRIMARY KEY,
    unit           TEXT NOT NULL DEFAULT '',
    area           TEXT NOT NULL DEFAULT '',
    equipment      TEXT NOT NULL DEFAULT '',
    tagNo          TEXT NOT NULL DEFAULT '',
    equipmentType  TEXT NOT NULL DEFAULT '',
    periode        TEXT NOT NULL DEFAULT 'Monthly',
    month          INTEGER CHECK (month IS NULL OR month BETWEEN 1 AND 12),
    week           INTEGER CHECK (week  IS NULL OR week  BETWEEN 1 AND 6),
    pic            TEXT NOT NULL DEFAULT '',
    lastDone       TEXT NOT NULL DEFAULT '',
    mp             INTEGER,
    hari           INTEGER,
    notes          TEXT NOT NULL DEFAULT '',
    startDate      TEXT NOT NULL DEFAULT '',
    takeoverAt     TEXT,
    takeoverFrom   TEXT,
    takeoverReason TEXT,
    createdAt      TEXT NOT NULL,
    updatedAt      TEXT NOT NULL,
    deletedAt      TEXT,
    updatedBy      TEXT,
    serverAt       TEXT NOT NULL
  );
-- @@
CREATE TABLE IF NOT EXISTS reports (
    id             TEXT PRIMARY KEY,
    tagNo          TEXT NOT NULL DEFAULT '',
    date           TEXT NOT NULL DEFAULT '',
    equipmentType  TEXT NOT NULL DEFAULT '',
    equipmentName  TEXT NOT NULL DEFAULT '',
    unit           TEXT NOT NULL DEFAULT '',
    area           TEXT NOT NULL DEFAULT '',
    periode        TEXT NOT NULL DEFAULT '',
    week           INTEGER,
    month          INTEGER,
    teknisi        TEXT NOT NULL DEFAULT '',
    approval       TEXT NOT NULL DEFAULT '',
    notes          TEXT NOT NULL DEFAULT '',
    ppe            TEXT NOT NULL DEFAULT '{}',
    aktivitas      TEXT NOT NULL DEFAULT '[]',
    spareParts     TEXT NOT NULL DEFAULT '[]',
    submittedAt    TEXT,
    updatedAt      TEXT NOT NULL,
    deletedAt      TEXT,
    updatedBy      TEXT,
    serverAt       TEXT NOT NULL
  );
-- @@
CREATE TABLE IF NOT EXISTS signatures (
    pmId            TEXT PRIMARY KEY,
    tagNo           TEXT NOT NULL DEFAULT '',
    equipmentName   TEXT NOT NULL DEFAULT '',
    tanggal         TEXT NOT NULL DEFAULT '',
    spvName         TEXT NOT NULL DEFAULT '',
    spvSignature    TEXT NOT NULL DEFAULT '',
    spvSignedAt     TEXT NOT NULL DEFAULT '',
    leaderName      TEXT NOT NULL DEFAULT '',
    leaderSignature TEXT NOT NULL DEFAULT '',
    leaderSignedAt  TEXT NOT NULL DEFAULT '',
    updatedAt       TEXT NOT NULL,
    updatedBy       TEXT,
    serverAt        TEXT NOT NULL
  );
-- @@
CREATE TABLE IF NOT EXISTS templates (
    equipmentType TEXT PRIMARY KEY,
    items         TEXT NOT NULL DEFAULT '[]',
    updatedAt     TEXT NOT NULL,
    updatedBy     TEXT,
    serverAt      TEXT NOT NULL
  );
-- @@
CREATE TABLE IF NOT EXISTS locks (
    scheduleId    TEXT PRIMARY KEY,
    equipmentName TEXT NOT NULL DEFAULT '',
    deviceId      TEXT NOT NULL,
    name          TEXT NOT NULL DEFAULT '',
    acquiredAt    TEXT NOT NULL,
    heartbeatAt   TEXT NOT NULL
  );
-- @@
CREATE TABLE IF NOT EXISTS audit_log (
    id       INTEGER PRIMARY KEY AUTOINCREMENT,
    at       TEXT NOT NULL,
    deviceId TEXT,
    ip       TEXT,
    action   TEXT NOT NULL,
    recordId TEXT
  );
-- @@
CREATE INDEX IF NOT EXISTS idx_schedules_serverAt ON schedules(serverAt);
-- @@
CREATE INDEX IF NOT EXISTS idx_reports_serverAt   ON reports(serverAt);
-- @@
CREATE INDEX IF NOT EXISTS idx_reports_date       ON reports(date);
-- @@
CREATE INDEX IF NOT EXISTS idx_signatures_serverAt ON signatures(serverAt);
-- @@
CREATE INDEX IF NOT EXISTS idx_audit_at           ON audit_log(at);
-- @@
INSERT INTO schedules (id, unit, area, equipment, tagNo, equipmentType, periode, month, week, pic, lastDone, mp, hari, notes, startDate, takeoverAt, takeoverFrom, takeoverReason, createdAt, updatedAt, deletedAt, updatedBy, serverAt) VALUES ('SCH-162', 'Unit 1', 'CTP-1', 'Big Gravity', 'TAG-201', 'gravity', 'Annual', 9, 1, '', '', NULL, NULL, '', '', NULL, NULL, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', NULL, 'IMPORT-SHEETS', strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT(id) DO UPDATE SET unit=excluded.unit, area=excluded.area, equipment=excluded.equipment, tagNo=excluded.tagNo, equipmentType=excluded.equipmentType, periode=excluded.periode, month=excluded.month, week=excluded.week, pic=excluded.pic, lastDone=excluded.lastDone, mp=excluded.mp, hari=excluded.hari, notes=excluded.notes, startDate=excluded.startDate, takeoverAt=excluded.takeoverAt, takeoverFrom=excluded.takeoverFrom, takeoverReason=excluded.takeoverReason, updatedAt=excluded.updatedAt, deletedAt=excluded.deletedAt, updatedBy=excluded.updatedBy, serverAt=excluded.serverAt WHERE excluded.updatedAt >= schedules.updatedAt AND schedules.deletedAt IS NULL;
-- @@
